"""Perfect Pairing

In a cooking contest, each contestant must create a dish with a total flavor score exactly matching the judge's magic number.
Contestants work in pairs, combining their flavor scores.
Given an array of flavor scores `scores` (each an integer) and the magic number `target`, write a function to count how many distinct pairs of scores can be combined to match the magic number.
A 'distinct pair' means a pair of indices (i, j) with i < j and scores[i] + scores[j] == target.
Return the count.
"""
import unittest
import math

def countPairs(scores, target):
    """Return the number of distinct pairs i<j with scores[i]+scores[j]==target.

    The requirement `i<j` simply means pairs should not be counted twice.
    The order of the pair doesn't matter.

    Rather than finding all pairs, we can count how many times each value appears.
    For each number `n` which appears `c` times, let `m = target - n` and `d` be how many times `m` appears.
    For each pair `n, m` there are `c * d` pairs. If we constrain `n < m` (or n < target / 2), we avoid duplicates.

    If `n = target / 2`, things get slightly trickier. If `target / 2` appears `c` times,
    there are `(c - 1) + (c - 2) + (c - 3) ... + (c - c)` pairs.
    """
    count = {}
    for i in scores:
        count[i] = count.get(i, 0) + 1
    total = 0
    for i in count:
        if i >= target / 2:
            continue
        total += count[i] * count.get(target - 1, 0)

    n = count.get(target / 2, 0)
    total += n * (n - 1) / 2

    return total























class TestSolution(unittest.TestCase):
    def test_data(self):
        self.assertEqual(countPairs([1, 2, 3, 4, 5], 5), 2)
        self.assertEqual(countPairs([1, 2, 3], 10), 0)
        self.assertEqual(countPairs([3, 3, 3], 6), 3)
        self.assertEqual(countPairs([], 5), 0)
